(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.27)*18+Math.sin(x*0.016+t*0.33)*12;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.025-t*0.5)*8+Math.cos(my*0.02+t*0.4)*6;
  const w2y = Math.cos(my*0.023+t*0.45)*8+Math.sin(mx*0.022-t*0.55)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.7],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*55,0.14,2.1,1.3],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*50,0.11,1.8,0.85]
  ];
  let aS=0,iS=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2=Math.sqrt((sx-sX*0.5-cx*0.5)**2+(sy-sY*0.5-cy*0.5)**2);
    aS+=Math.sin(d*f-t*sp)*w; iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    aS2+=Math.sin(d2*f*1.5-t*sp*0.8)*w*0.5; iS2+=Math.cos(d2*f*0.5+t*sp*0.4)*w*0.5;
  }
  const tw=8;
  const act=aS/tw,inh=iS/tw,act2=aS2/tw,inh2=iS2/tw;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=(Math.sin(dist*0.08+ang*2-t*2.5)+Math.cos(dist*0.06-ang*5+t*1.8))*0.2;
  const micro=(Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)+Math.sin(sx*0.2-sy*0.25+t*4)*0.5)*0.15;
  const laplacian=Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin(sx*0.15+2)*Math.sin(sy*0.15-2)
    +Math.sin(sx*0.15-2)*Math.sin(sy*0.15)+Math.sin(sx*0.15)*Math.sin(sy*0.15+2);
  const diffusion=laplacian*0.25;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((act2-inh2*0.6+spiral2+diffusion)*1.8);
  const coupled=Math.tanh((r1*0.6+r2*0.4+micro)*2.5);
  const edge=Math.abs(coupled)>0.6?(Math.abs(coupled)-0.6)*2.5:0;
  const glow=Math.exp(-edge*0.8)*0.4;
  const v=coupled*0.5+0.5;
  const pal=[
    [6,12,52],[12,45,95],[18,95,115],[25,155,135],[180,175,65],
    [215,130,60],[195,75,55],[130,35,60],[60,18,55],[20,10,42],[6,12,52]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const pulse=0.85+Math.sin(t*0.8)*0.08+Math.sin(coupled*Math.PI)*0.12;
  const eBoost=1.0+glow*0.6;
  const br=pulse*eBoost;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f+glow*30)*br)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f+glow*25)*br)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f+glow*45)*br)|0
  ];
}
